import{_ as h,C as s,o as u,c as m,j as a,a as n,G as t,a2 as i}from"./chunks/framework.BgSoyxN5.js";const q=JSON.parse('{"title":"TickerForge Stock Analysis & Ideas Partners | Stock Verdict, Insider Activity, Fund Moves, Stock Ideas","description":"Use TickerForge as a Telegram-native research layer for finance channels: stock research checks, recurring stock ideas, ready-to-share partner posts, tracked bot links, and measurable pilots.","frontmatter":{"title":"TickerForge Stock Analysis & Ideas Partners | Stock Verdict, Insider Activity, Fund Moves, Stock Ideas","description":"Use TickerForge as a Telegram-native research layer for finance channels: stock research checks, recurring stock ideas, ready-to-share partner posts, tracked bot links, and measurable pilots.","aside":false,"locale":"en","alternateLocales":{"en":"/partners/stock-analysis-and-ideas","ru":"/ru/partners/stock-analysis-and-ideas"},"pageClass":"partners-page"},"headers":[],"relativePath":"partners/stock-analysis-and-ideas.md","filePath":"partners/stock-analysis-and-ideas.md","lastUpdated":1788410450000}'),g={name:"partners/stock-analysis-and-ideas.md"},f={class:"partners-wide"},k={class:"partners-post-gallery"},y={class:"partners-wide"};function w(v,e,b,T,P,A){const o=s("PartnerPageAnalytics"),l=s("PartnerChannelCta"),r=s("PartnerPostImage"),d=s("PartnerCabinetCta"),c=s("PartnerReferralCta"),p=s("PartnerLeadForm");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"stock-analysis-ideas-partners",tabindex:"-1"},[n("Stock Analysis & Ideas Partners "),a("a",{class:"header-anchor",href:"#stock-analysis-ideas-partners","aria-label":'Permalink to "Stock Analysis & Ideas Partners"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Company research your channel can publish: ticker checks, ownership and insider context, and recurring stock ideas — with tracked links back to TickerForge.",-1)),e[2]||(e[2]=a("p",null,[n("This direction covers stock and company research only. Market and macro programming lives on the "),a("a",{href:"/partners/market-news"},"Market News"),n(" page, and portfolio diagnostics on the "),a("a",{href:"/partners/portfolio-health"},"Portfolio Health"),n(" page.")],-1)),t(o,{offer:"telegram_research",locale:"en"}),e[3]||(e[3]=a("div",{class:"partners-hero-actions"},[a("a",{class:"partners-button partners-button--primary",href:"#partner-contact","data-partner-event":"cta","data-partner-option":"propose_pilot","data-analytics-placement":"partner_hero"},"Propose a Pilot"),a("a",{class:"partners-button partners-button--secondary",href:"#research-formats","data-partner-event":"cta","data-partner-option":"see_formats","data-analytics-placement":"partner_hero"},"See The Formats")],-1)),t(l,{title:"See the research posts in the live channel",text:"The TickerForge public channel shows the same type of evidence blocks a partner can add to their own posts. Open it before deciding on a pilot format."}),e[4]||(e[4]=i('<p class="partners-locale-switch"><a href="/ru/partners/stock-analysis-and-ideas" hreflang="ru" data-partner-event="cta" data-partner-option="locale_ru" data-analytics-placement="partner_locale_switch">Читать эту страницу на русском</a></p><p class="partners-backlink">This is one of three partner directions. <a href="/partners">Back to all partner options</a> · <a href="/partners/market-news">Market news partnerships</a> · <a href="/partners/portfolio-health">Portfolio health partnerships</a> · <a href="/partners/requirements">Partner requirements</a></p><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="what-this-is" tabindex="-1">What This Is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What This Is&quot;">​</a></h2><p>A research layer for posts you already want to write. You keep your own voice and your own conclusion; TickerForge supplies the evidence block underneath it and a tracked link for readers who want to check the company themselves.</p><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>Per ticker</span><strong>Check the company you are writing about.</strong><p>Business quality, valuation context, ownership, insider activity, timing and risk for a single symbol.</p></div><div class="partners-card"><span>Recurring</span><strong>Ideas that give the channel a rhythm.</strong><p>Idea formats that pick their own companies each week, so the channel has something to publish without hunting for a topic.</p></div><div class="partners-card"><span>Measurable</span><strong>Every post carries a tracked link.</strong><p>Clicks, bot starts and referral attribution are visible in the Partner Cabinet.</p></div></div><h2 id="research-formats" tabindex="-1">Analysis &amp; Ideas Formats <a class="header-anchor" href="#research-formats" aria-label="Permalink to &quot;Analysis &amp;amp; Ideas Formats {#research-formats}&quot;">​</a></h2><p>Two kinds of content. Approved partners create the formats the Partner Cabinet supports today; anything else on this list can be requested as a pilot format.</p><h3 id="what-a-stock-analysis-post-is-built-on" tabindex="-1">What A Stock Analysis Post Is Built On <a class="header-anchor" href="#what-a-stock-analysis-post-is-built-on" aria-label="Permalink to &quot;What A Stock Analysis Post Is Built On&quot;">​</a></h3><p>A partner post is not a headline with a ticker in it. Every one is assembled from the same layer the product runs on, and that is the part a reader cannot get from a screenshot of a chart.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>60+ financial metrics per period, annual and quarterly.</strong> Revenue, margins, cash flow, debt, coverage, returns — collected per company and carried through every year and quarter we hold, so a change is measured rather than asserted.</li><li><strong>Compressed into one screen, colour-coded.</strong> The point is not that the data exists; it is that a reader sees year-over-year and quarter-over-quarter movement, fundamental risk, and where growth changed direction without opening a filing.</li><li><strong>Turnaround detection.</strong> Whether the quarterly numbers have started moving the other way after a stretch of decline — stated as a stage, not as an opinion.</li><li><strong>A numeric TickerForge score, and its own 5-year trend.</strong> The score is compared against its own 5-year moving average, so a reader sees whether the company is rated better or worse than its own history, not only where it sits today.</li><li><strong>Institutional ownership across 37 tracked funds.</strong> Not &quot;a fund bought it&quot;: the statistics for that specific stock across a fixed, named set of 37 funds, so the answer is comparable between companies and between quarters.</li><li><strong>Insider flow as a NET figure over 3 and 12 months.</strong> Not one eye-catching purchase — buying minus selling, over two windows, from people required to file every transaction.</li></ul></div><p>That is what makes it fast to react to: the assembly work is already done, and what your audience sees is the conclusion with its evidence attached.</p><h3 id="stock-analysis" tabindex="-1">Stock Analysis <a class="header-anchor" href="#stock-analysis" aria-label="Permalink to &quot;Stock Analysis&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Stock Verdict</strong><p>One ticker, one analysis block: quality, valuation context, ownership, timing, and risk.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Insider Activity</strong><p>Reported open-market insider buying or selling context for a ticker. Evidence, not a verdict.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Fund Moves</strong><p>Institutional sponsorship and fund-flow context based on available filings.</p></div></div></div><h3 id="stock-ideas" tabindex="-1">Stock Ideas <a class="header-anchor" href="#stock-ideas" aria-label="Permalink to &quot;Stock Ideas&quot;">​</a></h3><p>An idea here is a filter result with its reasoning attached, not a name somebody liked. Each format is a fixed rule that a company either passes or does not, run over the same 60+ metrics, the 37-fund ownership layer and the insider NET windows above.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>The rule is fixed and stated.</strong> Every format checks one specific thing and says which. A reader can disagree with the rule, which is more than they can do with a pick.</li><li><strong>The evidence travels with the idea.</strong> The post carries the numbers that qualified the company, so your audience is not asked to take a shortlist on trust.</li><li><strong>Each format names what it does NOT check.</strong> A turnaround format does not check valuation; an insider format does not check the business. Saying so is what keeps an idea from reading as a recommendation.</li><li><strong>One idea per format per week is reserved for you</strong>, so two partners never publish the same company in the same week.</li></ul></div><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Turnaround</strong><p>A company whose quarterly numbers have started moving the other way after a stretch of decline. Early evidence of recovery, not a recovery.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Insiders Are Buying</strong><p>Meaningful net open-market insider buying over recent months, from people who file every transaction.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Triple Rated</strong><p>One company clearing three fixed gates on the same day — the TickerForge score, the Piotroski F-Score and the Altman Z-Score. Says nothing about price.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Weekly Gems: Growth</strong><p>Revenue, earnings and cash flow all still moving the right way on the trailing twelve months, with the business quality holding up underneath.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Weekly Gems: Value</strong><p>Priced under a usable fair value estimate, where the business is not the reason for the discount.</p></div><div class="partners-format"><span>Available in Partner Cabinet</span><strong>Weekly Gems: Ownership</strong><p>A good business reading where insiders, tracked funds, or both have been adding.</p></div><div class="partners-format"><span>Available for partner pilots</span><strong>Accumulation Watchlists</strong><p>Themed watchlists — large caps, AI-era infrastructure, dividend compounders — built from the accumulation scan.</p></div></div></div><p>Six formats generate from the Cabinet with one tap. Pick the ones you want in the form at the bottom of this page; formats marked &quot;available for partner pilots&quot; are prepared with us rather than generated, and partner demand decides what becomes self-service next.</p><p>Three further formats are published by TickerForge in the public channel but not generated under a partner&#39;s name — Balance Sheet Stress, Insiders Are Selling, and Cash Flow Says Otherwise. Two of them are negative readings, and publishing &quot;this company is in distress&quot; under your own byline is a different editorial act from publishing an idea. <a href="/stock-ideas">See all nine formats and what each one deliberately does not check.</a></p><div class="partners-wide partners-routing-note"><p><strong>Every idea format, in detail.</strong> What each one checks, what it deliberately does not, how a company qualifies, and what the published card looks like — one page, nine formats.</p><a class="partners-button partners-button--primary" href="/stock-ideas" data-partner-event="cta" data-partner-option="stock_ideas" data-analytics-placement="partner_ideas_banner">Open all nine idea formats</a></div><h2 id="telegram-example-partner-posts" tabindex="-1">Telegram Example Partner Posts <a class="header-anchor" href="#telegram-example-partner-posts" aria-label="Permalink to &quot;Telegram Example Partner Posts&quot;">​</a></h2>',22)),a("div",f,[a("div",k,[t(r,{src:"/partners/examples/stock-research-sample.png",alt:"TickerForge partner post sample: stock verdict post with quality, ownership, timing and tracked bot link",caption:"Stock Verdict, as a partner would publish it."}),t(r,{src:"/partners/examples/turnaround-detected-sample.png",alt:"TickerForge partner post sample: Turnaround post with turnaround score and recovery stage",caption:"Turnaround, with score and recovery stage."}),t(r,{src:"/partners/examples/insider-buying-sample.png",alt:"TickerForge partner post sample: Insiders Are Buying post with net insider buying and pattern context",caption:"Insiders Are Buying, with net buying and pattern context."}),t(r,{src:"/partners/examples/idea-triple-rated-sample.png",alt:"TickerForge partner post sample: Triple-Rated post with three quality gates and each threshold marked",caption:"Triple-Rated, with each gate's threshold on the bar."}),t(r,{src:"/partners/examples/idea-gems-growth-sample.png",alt:"TickerForge partner post sample: Weekly Gems Growth post with revenue, earnings and cash flow",caption:"Weekly Gems: Growth, three lines each on its own direction."}),t(r,{src:"/partners/examples/idea-gems-value-sample.png",alt:"TickerForge partner post sample: Weekly Gems Value post with price against the fair value estimate",caption:"Weekly Gems: Value, price against the estimate."}),t(r,{src:"/partners/examples/idea-gems-ownership-sample.png",alt:"TickerForge partner post sample: Weekly Gems Ownership post with fund and insider activity",caption:"Weekly Gems: Ownership, both filing sides."})])]),t(d,{locale:"en"}),e[5]||(e[5]=i('<h2 id="how-a-stock-analysis-ideas-pilot-works" tabindex="-1">How A Stock Analysis &amp; Ideas Pilot Works <a class="header-anchor" href="#how-a-stock-analysis-ideas-pilot-works" aria-label="Permalink to &quot;How A Stock Analysis &amp; Ideas Pilot Works&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Tell us the format</strong><p>Use the form below: pick Stock Analysis &amp; Ideas and the research formats your audience would actually read.</p></div><div><span>2</span><strong>Get partner access</strong><p>Approved partners get a Standard seat for the pilot window and the Partner Cabinet opens in Telegram.</p></div><div><span>3</span><strong>Create the post</strong><p>Generate a supported format in the Cabinet, or receive a prepared post for a format that is still a pilot request.</p></div><div><span>4</span><strong>Publish with your own voice</strong><p>Keep your analysis, add the TickerForge evidence block, the disclaimer, and your tracked link.</p></div><div><span>5</span><strong>Measure and decide</strong><p>Cabinet statistics show what the posts produced; you decide whether to continue, change format, or stop.</p></div></div></div><h2 id="measurement" tabindex="-1">How Measurement Works <a class="header-anchor" href="#measurement" aria-label="Permalink to &quot;How Measurement Works {#measurement}&quot;">​</a></h2><p>Every generated post receives a short tracked link. The link itself is opaque — it does not encode partner code, month, format, workflow, or ticker. Those values are stored as reporting fields instead.</p><p>The Partner Cabinet currently includes:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Statistics:</strong> partner-level tracked clicks, referrals, current-month paid referrals, and a compact current-month breakdown by post type.</li><li><strong>Monthly Report:</strong> current or previous month XLSX with Summary and Posts sheets.</li><li><strong>Raw clicks:</strong> link hits, not unique people.</li><li><strong>Bot starts:</strong> unique Telegram users whose first partner-post start came from that post.</li><li><strong>New referrals:</strong> users that the existing Ambassador model first bound to the partner after that start.</li><li><strong>Paid subscriptions:</strong> current active paid-plan snapshot among those referrals, not a historical payment ledger.</li></ul></div><h2 id="what-partners-get" tabindex="-1">What Partners Get <a class="header-anchor" href="#what-partners-get" aria-label="Permalink to &quot;What Partners Get&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>Ready-made company research posts, generated on demand rather than written.</li><li>Weekly stock ideas with the evidence that qualified them attached.</li><li>The channel image and formatting, so a post can be forwarded as it arrives.</li><li>Tracked links inside every post format.</li><li>Posts in English or Russian, switched in the Cabinet.</li><li>Cabinet statistics per post type, and a monthly XLSX report.</li><li>One idea per format per week reserved for you, so two partners are not handed the same company.</li><li>Future API or custom feed discussion if the pilot works.</li></ul></div><p>Eligibility, posting commitments, and access rules are the same for every direction and live on the <a href="/partners/requirements">partner requirements</a> page.</p><h2 id="best-for" tabindex="-1">Best For <a class="header-anchor" href="#best-for" aria-label="Permalink to &quot;Best For&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>Telegram channels and investing communities that cover individual companies.</li><li>Instagram and TikTok creators who need a defensible stock card instead of a hot take.</li><li>YouTube channels that open with a company and want the numbers ready before filming.</li><li>LinkedIn writers publishing company analysis to a professional audience.</li><li>Newsletters and Discord groups running a recurring idea column.</li><li>Anyone who wants to talk about a company without spending an evening in its filings first.</li></ul></div><h2 id="partner-access" tabindex="-1">Partner Access Model <a class="header-anchor" href="#partner-access" aria-label="Permalink to &quot;Partner Access Model {#partner-access}&quot;">​</a></h2><p>The first pilot includes a temporary creator access seat.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>What you get:</strong> Standard-level access for the pilot window, usually 30 days, plus ready-to-post research, tracked links, referral attribution, and Cabinet statistics.</li><li><strong>What you commit to:</strong> 3 qualified Telegram posts during the pilot, then 2-4 per month if it continues.</li><li><strong>Who qualifies:</strong> finance channels from roughly 1,000 real subscribers; smaller, strongly engaged communities case by case.</li><li><strong>What counts as a qualified post:</strong> a real TickerForge evidence block, your own analysis, an educational disclaimer, and a tracked bot or product link.</li><li><strong>If the cadence stops:</strong> complimentary access pauses and reverts to the normal free tier.</li></ul></div><p>Full eligibility rules and the exact conditions under which access ends are on the <a href="/partners/requirements">partner requirements</a> page.</p>',15)),t(c),e[6]||(e[6]=i('<h2 id="what-tickerforge-is-not" tabindex="-1">What TickerForge Is Not <a class="header-anchor" href="#what-tickerforge-is-not" aria-label="Permalink to &quot;What TickerForge Is Not&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>TickerForge is not:</p><ul><li>a trading robot</li><li>a signal channel</li><li>a broker</li><li>a copy-trading system</li><li>a promise of profit</li><li>personalized financial advice</li></ul><p>TickerForge is educational decision-support software for reviewing stock, portfolio, ownership, and market context before acting.</p></div><h2 id="partner-contact" tabindex="-1">Request A Stock Analysis &amp; Ideas Format <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Request A Stock Analysis &amp; Ideas Format {#partner-contact}&quot;">​</a></h2><p>Tell us about your channel, audience, and which research formats you want first. Useful details: channel link, audience size, language, main topic, posting frequency, and your first ticker ideas.</p>',4)),a("div",y,[t(p,{source:"partners_telegram_research","default-program":"TELEGRAM_RESEARCH"})]),e[7]||(e[7]=i('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/partners">All partner options</a></li><li><a href="/partners/cabinet">How Partner Cabinet works</a></li><li><a href="/partners/requirements">Partner requirements</a></li><li><a href="/partners/market-news">Market news partners</a></li><li><a href="/partners/portfolio-health">Portfolio health partners</a></li><li><a href="/stock-widget">Stock Check Widget</a></li><li><a href="/smart-money-radar">Smart Money and Insider Radar</a></li><li><a href="/ambassador">Ambassador / referral program</a></li></ul>',2))])}const S=h(g,[["render",w]]);export{q as __pageData,S as default};
